import sys
from collections import defaultdict

n_nodes, n_edges = (int(x) for x in sys.stdin.readline().split())
graph = {}

def is_ring(cur_node, used={}):
    if cur_node in used:
        return True
    if cur_node not in graph:
        return False
    if len(graph[cur_node]) == 0:
        return False
    if len(graph[cur_node]) != 1:
        return False
    used[cur_node] = True
    return is_ring(graph[cur_node][0], used)

def is_bus(cur_node, used={}):

    if cur_node in used:
        return False
    if cur_node not in graph:
        return True
    if len(graph[cur_node]) == 0:
        return True
    if len(graph[cur_node]) != 1:
        return False

    used[cur_node] = True
    return is_bus(graph[cur_node][0], used)

def is_star():
    counts = {}
    used = {}
    def gen_counts(cur_node):
        if cur_node not in counts:
            counts[cur_node] = 0
        if cur_node in used:
            return
        used[cur_node] = True
        if cur_node not in graph:
            return
        for connected in graph[cur_node]:
            if connected not in counts:
                counts[connected] = 0
            counts[connected] += 1
            gen_counts(connected)

    for i in graph:
        gen_counts(i)

    n_others, n_centers, n_leaves = 0, 0, 0

    for n, count in counts.items():
        if count == 1:
            n_leaves += 1
        elif count == 0:
            n_centers += 1
        else:
            n_others += 1

    return (n_others == 0) and (n_centers == 1) and (n_leaves == len(counts.items())-1)

for i in range(n_edges):
    node1, node2 = (int(x) for x in sys.stdin.readline().split())
    if node1 not in graph:
        graph[node1] = []
    graph[node1].append(node2)

if is_bus(1):
    print("bus topology")
elif is_ring(1):
    print("ring topology")
elif is_star():
    print("star topology")
else:
    print("unknown topology")
